// Normalizes incoming entries into Cyber Daily JSON format
const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;
  // Handle CISA KEV or HN feeds
  if (data.cveID) {
    output.push({
      id: `cisa-${data.cveID.toLowerCase()}`,
      title: `CISA Alert: ${data.vendorProject} ${data.product} (${data.cveID})`,
      summary: data.shortDescription || data.vulnerabilityName,
      category: 'CVE / Vulnerabilities',
      source: 'CISA KEV',
      sourceUrl: `https://nvd.nist.gov/vuln/detail/${data.cveID}`,
      publishedAt: new Date().toISOString(),
      tags: [data.cveID, 'CISA-KEV', 'Exploited'],
      cveId: data.cveID,
      severity: 'Critical',
      cvssScore: 9.0,
      whyItMatters: 'Actively weaponized in the wild according to CISA.',
      technicalDetails: `Affects ${data.vendorProject} ${data.product}.`,
      affectedProducts: [`${data.vendorProject} ${data.product}`],
      recommendations: data.requiredAction || 'Apply vendor updates.'
    });
  } else if (data.title) {
    output.push({
      id: `feed-${data.objectID || Math.random().toString(36).substring(2, 8)}`,
      title: data.title,
      summary: data.story_text || `Discussion: ${data.title}`,
      category: 'Cybersecurity News',
      source: 'Hacker News InfoSec',
      sourceUrl: data.url || `https://news.ycombinator.com/item?id=${data.objectID}`,
      publishedAt: data.created_at || new Date().toISOString(),
      tags: ['Security', 'Community'],
      severity: 'Medium',
      cvssScore: 0.0
    });
  }
}

return output.map(o => ({ json: o }));
